use std::collections::{BTreeMap, HashMap};
use std::io::{self, Read};

const IN_PROGRESS: u8 = 1;
const DONE: u8 = 2;

#[derive(Clone, Copy)]
enum Op {
    Ge,
    Le,
    Eq,
    Gt,
    Lt,
}

impl Op {
    fn parse(s: &str) -> Option<Op> {
        match s {
            ">=" => Some(Op::Ge),
            "<=" => Some(Op::Le),
            "=" => Some(Op::Eq),
            ">" => Some(Op::Gt),
            "<" => Some(Op::Lt),
            _ => None,
        }
    }

    fn symbol(self) -> &'static str {
        match self {
            Op::Ge => ">=",
            Op::Le => "<=",
            Op::Eq => "=",
            Op::Gt => ">",
            Op::Lt => "<",
        }
    }

    fn holds(self, found: u64, wanted: u64) -> bool {
        match self {
            Op::Ge => found >= wanted,
            Op::Le => found <= wanted,
            Op::Eq => found == wanted,
            Op::Gt => found > wanted,
            Op::Lt => found < wanted,
        }
    }
}

fn parse_version(s: &str) -> Option<u64> {
    if s.is_empty() || s.len() > 6 || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

struct Resolver {
    versions: HashMap<String, u64>,
    // package -> dependency -> constraints, both maps ordered by byte order
    deps: HashMap<String, BTreeMap<String, Vec<(Op, u64)>>>,
    state: HashMap<String, u8>,
    stack: Vec<String>,
    order: Vec<String>,
    errors: Vec<String>,
}

impl Resolver {
    fn visit(&mut self, u: &str) {
        self.state.insert(u.to_string(), IN_PROGRESS);
        self.stack.push(u.to_string());
        let deps = self.deps.get(u).cloned().unwrap_or_default();
        for (dep, constraints) in &deps {
            let found = match self.versions.get(dep) {
                Some(&w) => w,
                None => {
                    self.errors
                        .push(format!("error: missing dependency {} of {}", dep, u));
                    continue;
                }
            };
            for (op, wanted) in constraints {
                if !op.holds(found, *wanted) {
                    self.errors.push(format!(
                        "error: {} needs {} {} {} but found {}",
                        u,
                        dep,
                        op.symbol(),
                        wanted,
                        found
                    ));
                }
            }
            match self.state.get(dep).copied() {
                Some(IN_PROGRESS) => {
                    let pos = self.stack.iter().position(|x| x == dep).unwrap();
                    let mut chain: Vec<&str> =
                        self.stack[pos..].iter().map(|s| s.as_str()).collect();
                    chain.push(dep.as_str());
                    self.errors
                        .push(format!("error: cycle {}", chain.join(" -> ")));
                }
                Some(_) => {}
                None => self.visit(dep),
            }
        }
        self.stack.pop();
        self.state.insert(u.to_string(), DONE);
        self.order.push(u.to_string());
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut r = Resolver {
        versions: HashMap::new(),
        deps: HashMap::new(),
        state: HashMap::new(),
        stack: Vec::new(),
        order: Vec::new(),
        errors: Vec::new(),
    };

    // Phase 1: parse declarations in line order.
    let mut well_formed_deps: Vec<(String, String, Op, u64)> = Vec::new();
    let mut installs: Vec<String> = Vec::new();
    for (idx, line) in input.lines().enumerate() {
        let lineno = idx + 1;
        if line.is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split(' ').collect();
        match f[0] {
            "pkg" if f.len() == 3 => match parse_version(f[2]) {
                Some(v) => {
                    if r.versions.contains_key(f[1]) {
                        r.errors.push(format!("error: duplicate package {}", f[1]));
                    } else {
                        r.versions.insert(f[1].to_string(), v);
                    }
                }
                None => r.errors.push(format!("error: bad line {}", lineno)),
            },
            "dep" if f.len() == 5 => match (Op::parse(f[3]), parse_version(f[4])) {
                (Some(op), Some(v)) => {
                    well_formed_deps.push((f[1].to_string(), f[2].to_string(), op, v))
                }
                _ => r.errors.push(format!("error: bad line {}", lineno)),
            },
            "install" if f.len() == 2 => installs.push(f[1].to_string()),
            _ => r.errors.push(format!("error: bad line {}", lineno)),
        }
    }

    // Phase 2: attach constraints to declared packages.
    for (name, dep, op, v) in well_formed_deps {
        if !r.versions.contains_key(&name) {
            r.errors
                .push(format!("error: dep for unknown package {}", name));
            continue;
        }
        r.deps
            .entry(name)
            .or_default()
            .entry(dep)
            .or_default()
            .push((op, v));
    }

    // Phase 3: resolve installs in line order.
    for name in &installs {
        if !r.versions.contains_key(name) {
            r.errors.push(format!("error: unknown package {}", name));
            continue;
        }
        if r.state.get(name).copied() != Some(DONE) {
            r.visit(name);
        }
    }

    if !r.errors.is_empty() {
        for e in &r.errors {
            println!("{}", e);
        }
        std::process::exit(1);
    }
    for name in &r.order {
        println!("install {} {}", name, r.versions[name]);
    }
}
